from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Find the three-cell, non-background line that serves as the template.
    runs = []
    for r in range(h):
        for c in range(w - 2):
            cells = [(r, c + i) for i in range(3)]
            if all(grid[rr][cc] != bg for rr, cc in cells):
                runs.append((cells, (0, 1)))
    for r in range(h - 2):
        for c in range(w):
            cells = [(r + i, c) for i in range(3)]
            if all(grid[rr][cc] != bg for rr, cc in cells):
                runs.append((cells, (1, 0)))

    if not runs:
        return [row[:] for row in grid]

    # Prefer a run containing rare colors, as in the embedded template.
    def run_score(item):
        cells, _ = item
        colors = [grid[r][c] for r, c in cells]
        return (len(set(colors)), sum(1 / counts[x] for x in colors))

    template, direction = max(runs, key=run_score)
    template_set = set(template)
    markers = Counter(
        grid[r][c] for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in template_set
    )
    if not markers:
        return [row[:] for row in grid]
    marker_color = markers.most_common(1)[0][0]
    targets = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == marker_color and (r, c) not in template_set
    ]

    out = [row[:] for row in grid]
    dr, dc = direction
    for r, c in targets:
        for i, (tr, tc) in enumerate(template):
            rr = r + (i - 1) * dr
            cc = c + (i - 1) * dc
            if 0 <= rr < h and 0 <= cc < w and (rr, cc) not in template_set:
                out[rr][cc] = grid[tr][tc]
    return out
